import {chromium} from 'playwright';import {spawn} from 'node:child_process';import assert from 'node:assert/strict';import fs from 'node:fs/promises';
const server=spawn(process.execPath,['node_modules/vite/bin/vite.js','preview','--host','127.0.0.1','--port','4195','--strictPort']);await new Promise(r=>server.stdout.on('data',d=>{if(d.toString().includes('Local:'))r()}));const b=await chromium.launch({executablePath:'/workspace/browser-tmp/chromium',args:['--no-sandbox']});const results=[];
try{for(const width of [1500,390])for(const lang of ['ru','en']){
const p=await b.newPage({viewport:{width,height:1000}});await p.route(/mc\.yandex/,r=>r.abort());await p.goto('http://127.0.0.1:4195');await p.locator('input[type=file]').setInputFiles('test/fixtures/import-v2/baseline-mythic.json');await p.locator('.direct-mode').waitFor();if(lang==='en')await p.getByRole('button',{name:'Switch to English',exact:true}).click();assert.equal(await p.locator('.info-block--debug').count(),0);assert.equal(await p.locator('[data-selected-hex]').count(),1);await p.getByRole('button',{name:lang==='ru'?'Найти объект':'Find object',exact:true}).click();for(const mode of ['read','edit']){if(mode==='edit'){const measure=()=>p.locator('.info-block--hex').evaluate(card=>{const top=card.getBoundingClientRect().top;return [...card.children].filter(e=>e.matches('p,.direct-line')).map(e=>({text:e.textContent,y:e.getBoundingClientRect().top-top,height:e.getBoundingClientRect().height,lineHeight:getComputedStyle(e).lineHeight}));});const before=await measure();await p.locator('.direct-mode').click();assert.deepEqual(await measure(),before,'common read/edit row geometry');}for(const type of ['region','settlement','river','lake','kingdom']){await p.locator('.map-names select').selectOption(type);const row=p.locator('[data-target-key]:enabled').first();await row.click();await p.waitForFunction(()=>document.activeElement?.matches('.info-block--hex'));assert.equal(await p.locator('[data-selected-hex]').count(),1);assert.equal(await p.locator('.map-names [data-inline-name]').count(),0);}}await p.locator('.map-names').scrollIntoViewIfNeeded();assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await p.screenshot({type:'jpeg',quality:85,path:`/workspace/hx010-${lang}-${width}.jpg`});results.push({lang,width,debug_absent:true,five_types_both_modes:true,one_selected_overlay:true,overflow:false});await p.close();}
for(const query of ['', '?debug=0','?debug=false','?debug=1']){const p=await b.newPage();await p.goto('http://127.0.0.1:4195/'+query);await p.locator('input[type=file]').setInputFiles('test/fixtures/import-v2/baseline-mythic.json');await p.locator('.direct-mode').waitFor();assert.equal(await p.locator('.info-block--debug').count(),query==='?debug=1'?1:0);if(query==='?debug=1'){assert.equal(await p.locator('.info-block--debug').getAttribute('open'),null);await p.locator('.info-block--debug summary').click();assert.ok(await p.locator('.info-block--debug').getAttribute('open')!==null);}await p.close();}await fs.writeFile('/workspace/hx010-ui.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results));}finally{await b.close();server.kill()}
